export const getUpdateRecommendationUrl = (recommendationId: string,) => {




  return `/api/recommendations/${recommendationId}`
}

/**
 * @summary Mark a study recommendation complete or incomplete
 */
export const updateRecommendation = async (recommendationId: string,
    recommendationUpdate: RecommendationUpdate, options?: Parameters<typeof customFetch>[1]): Promise<StudyRecommendation> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<StudyRecommendation>(getUpdateRecommendationUrl(recommendationId),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(recommendationUpdate)
  }
);}





